func SinkSelect(q *ent.SinkQuery, m *api.SinkSelect) {
	if !m.GetAll() {
		fields := SinkSelectedFields(m)
		q.Select(fields...)
	}
	if m.HasNode() {
		q.WithNode(func(q *ent.NodeQuery) {
			q.Where(node.DateErasedIsNil())
			NodeSelect(q, m.GetNode())
		})
	}
	if m.HasDevice() {
		q.WithDevice(func(q *ent.DeviceQuery) {
			q.Where(device.DateErasedIsNil())
			DeviceSelect(q, m.GetDevice())
		})
	}
}

func SinkSelectInit(q *ent.SinkQuery, m *api.SinkSelect) {
	if m != nil {
		SinkSelect(q, m)
	} else {
		q.WithNode(selectNodeKey)
		q.WithDevice(selectDeviceKey)
	}
}

func (s SinkServiceServer) Patch(ctx context.Context, req *api.SinkPatchRequest) (*api.Sink, error) {
	doc, err := ormpatch.FromPatchRequest(sinkOrmEntity, req.ProtoReflect(), func(ed graph.Edge, ref protoreflect.Message) (protoreflect.Value, error) {
		switch ed.Number() {
		case 8:
			k, err := NodeGetKey(ctx, s.Db, ref.Interface().(*api.NodeRef))
			if err != nil {
				return protoreflect.Value{}, err
			}
			return protoreflect.ValueOfBytes(k[:]), nil
		}
		return protoreflect.Value{}, status.Errorf(codes.Internal, "no key resolver for edge: %s", ed.Name())
	})
	if err != nil {
		if _, ok := status.FromError(err); ok {
			return nil, err
		}
		if errors.Is(err, ormpatch.ErrRequestLayout) {
			return nil, status.Errorf(codes.Internal, "%s", err)
		}
		if errors.Is(err, ormpatch.ErrUnsupported) {
			return nil, status.Errorf(codes.Unimplemented, "%s", err)
		}
		return nil, status.Errorf(codes.InvalidArgument, "%s", err)
	}

	return s.apply(ctx, req.GetRef(), doc, api.SinkService_Patch_FullMethodName)
}

func SinkGetKey(ctx context.Context, db *ent.Client, ref *api.SinkRef) (uuid.UUID, error) {
	var z uuid.UUID
	if ref.HasId() {
		if v, err := entuuid.FromBytes(ref.GetId()); err != nil {
			return z, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return v, nil
		}
	}

	p, err := SinkPick(ref)
	if err != nil {
		return z, err
	}

	v, err := db.Sink.Query().Where(p).OnlyId(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			return z, status.Error(codes.NotFound, "Sink not found")
		}
		return z, err
	}

	return v, nil
}

var sinkOrmEntity = ormpatch.MustEntityOf(api.File_shale_storage_proto, "Sink")

var sinkPatchColumns = entpatch.Columns{
	1: sink.FieldId, 4: sink.FieldAlias, 5: sink.FieldName, 6: sink.FieldDesc, 7: sink.FieldLabels, 8: sink.NodeColumn, 9: sink.DeviceColumn, 10: sink.FieldPath, 11: sink.FieldCapacity, 12: sink.FieldFree, 13: sink.FieldDateUpdated, 14: sink.FieldDateErased, 15: sink.FieldDateCreated, 16: sink.FieldPressure, 17: sink.FieldCapabilities, 18: sink.FieldAttachment, 19: sink.FieldAcceptWrites, 20: sink.FieldDateSeen, 21: sink.FieldUploadsInFlight, 22: sink.FieldDateReconciled, 23: sink.FieldReportedBy, 24: sink.FieldWarnings, 25: sink.FieldCapacityClamped, 26: sink.FieldLaminae}

func (s SinkServiceServer) Apply(ctx context.Context, req *api.SinkApplyRequest) (*api.Sink, error) {
	if !req.HasPatch() {
		return nil, status.Errorf(codes.InvalidArgument, "%s", ormpatch.ErrNoPatch)
	}
	return s.apply(ctx, req.GetRef(), req.GetPatch(), api.SinkService_Apply_FullMethodName)
}

func (s SinkServiceServer) apply(ctx context.Context, ref *api.SinkRef, doc *patchpb.Patch, by string) (*api.Sink, error) {
	plan := &ormpatch.Plan{Entity: sinkOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(sinkOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, sinkPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := SinkGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &api.SinkRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, sink.IdEQ(k))
	if err != nil {
		return nil, err
	}

	if mod == nil {
		q := st.Db.Sink.Query().Where(p)
		if pred != nil {
			q.Where(predicate.Sink(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.Sink.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Sink not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.Sink.Update().Where(p)
		if pred != nil {
			q.Where(predicate.Sink(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "Sink already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "Sink: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.Sink.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Sink not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	if mod != nil {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:    by,
			Key:   k,
			Patch: doc,
		}); err != nil {
			return nil, err
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s SinkServiceServer) Erase(ctx context.Context, req *api.SinkRef) (*api.SinkEraseResponse, error) {
	p, err := SinkPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.Sink.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &api.SinkEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = sink.And(p, sink.IdEQ(v))
	}

	u := st.Db.Sink.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  api.SinkService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &api.SinkEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// SinkPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a Sink is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasSinkWith`, where no narrowing of a Sink
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func SinkPick(req *api.SinkRef) (predicate.Sink, error) {
	p, err := pickSink(req)
	if err != nil {
		return nil, err
	}

	return sink.And(sink.DateErasedIsNil(), p), nil
}

func pickSink(req *api.SinkRef) (predicate.Sink, error) {
	switch req.WhichKey() {
	case api.SinkRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return sink.IdEQ(v), nil
		}
	case api.SinkRef_Alias_case:
		return sink.AliasEQ(req.GetAlias()), nil
	case api.SinkRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Sink")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
